diff --git a/encryption/encryption.go b/encryption/encryption.go
new file mode 100644
index 0000000..6326aab
--- /dev/null
+++ b/encryption/encryption.go
@@ -0,0 +1,412 @@
+package encryption
+
+import (
+	"crypto/aes"
+	"crypto/cipher"
+	"crypto/hmac"
+	"crypto/rand"
+	"crypto/sha256"
+	"encoding/base64"
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"hash"
+	"io"
+	"os"
+	"strings"
+
+	"golang.org/x/crypto/pbkdf2"
+)
+
+var ErrInvalidKey = errors.New("invalid key length: must be 32 bytes")
+
+type Config struct {
+	Enabled    bool   `yaml:"enabled,omitempty" json:"enabled,omitempty"`
+	KeySource  string `yaml:"key_source,omitempty" json:"key_source,omitempty"`
+	KeyEnvVar  string `yaml:"key_env_var,omitempty" json:"key_env_var,omitempty"`
+	KeyFile    string `yaml:"key_file,omitempty" json:"key_file,omitempty"`
+	Key        string `yaml:"key,omitempty" json:"key,omitempty"`
+	Passphrase string `yaml:"passphrase,omitempty" json:"passphrase,omitempty"`
+	Salt       string `yaml:"salt,omitempty" json:"salt,omitempty"`
+}
+
+func (c Config) Validate() error {
+	if !c.Enabled {
+		return nil
+	}
+
+	source := strings.ToLower(strings.TrimSpace(c.KeySource))
+	if source == "" {
+		return errors.New("key_source is required when encryption is enabled")
+	}
+
+	switch source {
+	case "env":
+		if c.KeyFile != "" || c.Key != "" || c.Passphrase != "" || c.Salt != "" {
+			return errors.New("key_source 'env' fields are mutually exclusive with other key source fields")
+		}
+		if strings.TrimSpace(c.KeyEnvVar) == "" {
+			return errors.New("key_env_var is required for env key source")
+		}
+	case "file":
+		if c.KeyEnvVar != "" || c.Key != "" || c.Passphrase != "" || c.Salt != "" {
+			return errors.New("key_source 'file' fields are mutually exclusive with other key source fields")
+		}
+		if strings.TrimSpace(c.KeyFile) == "" {
+			return errors.New("key_file is required for file key source")
+		}
+	case "literal":
+		if c.KeyEnvVar != "" || c.KeyFile != "" || c.Passphrase != "" || c.Salt != "" {
+			return errors.New("key_source 'literal' fields are mutually exclusive with other key source fields")
+		}
+		if strings.TrimSpace(c.Key) == "" {
+			return errors.New("key is required for literal key source")
+		}
+	case "derive":
+		if c.KeyEnvVar != "" || c.KeyFile != "" || c.Key != "" {
+			return errors.New("key_source 'derive' fields are mutually exclusive with other key source fields")
+		}
+		if strings.TrimSpace(c.Passphrase) == "" {
+			return errors.New("passphrase is required for derive key source")
+		}
+		if strings.TrimSpace(c.Salt) == "" {
+			return errors.New("salt is required for derive key source")
+		}
+	default:
+		return fmt.Errorf("unsupported key_source: %s", c.KeySource)
+	}
+
+	return nil
+}
+
+func decodeBase64(s string) ([]byte, error) {
+	s = strings.TrimSpace(s)
+	if b, err := base64.StdEncoding.DecodeString(s); err == nil {
+		return b, nil
+	}
+	if b, err := base64.RawStdEncoding.DecodeString(s); err == nil {
+		return b, nil
+	}
+	if b, err := base64.URLEncoding.DecodeString(s); err == nil {
+		return b, nil
+	}
+	return base64.RawURLEncoding.DecodeString(s)
+}
+
+func decodeBase64Key(s string) ([]byte, error) {
+	b, err := decodeBase64(s)
+	if err != nil {
+		return nil, fmt.Errorf("invalid base64 encoding: %w", err)
+	}
+	if len(b) != 32 {
+		return nil, fmt.Errorf("%w: decoded key length is %d bytes, expected 32", ErrInvalidKey, len(b))
+	}
+	return b, nil
+}
+
+func LoadKey(cfg Config) ([]byte, error) {
+	c := cfg
+	c.Enabled = true
+	if err := c.Validate(); err != nil {
+		return nil, err
+	}
+
+	source := strings.ToLower(strings.TrimSpace(cfg.KeySource))
+	switch source {
+	case "env":
+		val, ok := os.LookupEnv(cfg.KeyEnvVar)
+		if !ok || strings.TrimSpace(val) == "" {
+			return nil, fmt.Errorf("encryption key env var %q is unset or empty", cfg.KeyEnvVar)
+		}
+		return decodeBase64Key(val)
+
+	case "file":
+		content, err := os.ReadFile(cfg.KeyFile)
+		if err != nil {
+			return nil, fmt.Errorf("failed to read encryption key file %s: %w", cfg.KeyFile, err)
+		}
+		return decodeBase64Key(string(content))
+
+	case "literal":
+		return decodeBase64Key(cfg.Key)
+
+	case "derive":
+		if strings.TrimSpace(cfg.Passphrase) == "" {
+			return nil, errors.New("empty passphrase rejected for key derivation")
+		}
+		saltBytes, err := decodeBase64(cfg.Salt)
+		if err != nil {
+			return nil, fmt.Errorf("failed to decode base64 salt: %w", err)
+		}
+		if len(saltBytes) < 16 {
+			return nil, fmt.Errorf("salt must be at least 16 bytes, got %d", len(saltBytes))
+		}
+		return pbkdf2.Key([]byte(cfg.Passphrase), saltBytes, 10000, 32, sha256.New), nil
+
+	default:
+		return nil, fmt.Errorf("unsupported key_source: %s", cfg.KeySource)
+	}
+}
+
+type Encryptor struct {
+	key []byte
+}
+
+func NewEncryptor(key []byte) (*Encryptor, error) {
+	if len(key) != 32 {
+		return nil, fmt.Errorf("%w: key must be 32 bytes, got %d", ErrInvalidKey, len(key))
+	}
+	k := make([]byte, 32)
+	copy(k, key)
+	return &Encryptor{key: k}, nil
+}
+
+type encryptWriter struct {
+	w             io.Writer
+	key           []byte
+	gcm           cipher.AEAD
+	mac           hash.Hash
+	buf           []byte
+	headerWritten bool
+	closed        bool
+}
+
+func (e *Encryptor) EncryptWriter(w io.Writer) io.WriteCloser {
+	block, _ := aes.NewCipher(e.key)
+	gcm, _ := cipher.NewGCM(block)
+	mac := hmac.New(sha256.New, e.key)
+
+	return &encryptWriter{
+		w:   w,
+		key: e.key,
+		gcm: gcm,
+		mac: mac,
+		buf: make([]byte, 0, 65536),
+	}
+}
+
+func (ew *encryptWriter) Write(p []byte) (int, error) {
+	if ew.closed {
+		return 0, errors.New("write to closed encryptWriter")
+	}
+
+	if !ew.headerWritten {
+		if _, err := ew.w.Write([]byte{0x4F, 0x44, 0x01}); err != nil {
+			return 0, err
+		}
+		ew.headerWritten = true
+	}
+
+	total := len(p)
+	for len(p) > 0 {
+		space := 65536 - len(ew.buf)
+		if space > len(p) {
+			space = len(p)
+		}
+		ew.buf = append(ew.buf, p[:space]...)
+		p = p[space:]
+		if len(ew.buf) == 65536 {
+			if err := ew.flushChunk(); err != nil {
+				return 0, err
+			}
+		}
+	}
+	return total, nil
+}
+
+func (ew *encryptWriter) flushChunk() error {
+	if len(ew.buf) == 0 {
+		return nil
+	}
+
+	nonce := make([]byte, 12)
+	if _, err := rand.Read(nonce); err != nil {
+		return fmt.Errorf("failed to generate nonce: %w", err)
+	}
+
+	ciphertext := ew.gcm.Seal(nil, nonce, ew.buf, nil)
+	chunkLen := uint32(len(nonce) + len(ciphertext))
+
+	lenBuf := make([]byte, 4)
+	binary.BigEndian.PutUint32(lenBuf, chunkLen)
+
+	ew.mac.Write(lenBuf)
+	ew.mac.Write(nonce)
+	ew.mac.Write(ciphertext)
+
+	if _, err := ew.w.Write(lenBuf); err != nil {
+		return err
+	}
+	if _, err := ew.w.Write(nonce); err != nil {
+		return err
+	}
+	if _, err := ew.w.Write(ciphertext); err != nil {
+		return err
+	}
+
+	ew.buf = ew.buf[:0]
+	return nil
+}
+
+func (ew *encryptWriter) Close() error {
+	if ew.closed {
+		return nil
+	}
+	ew.closed = true
+
+	if !ew.headerWritten {
+		if _, err := ew.w.Write([]byte{0x4F, 0x44, 0x01}); err != nil {
+			return err
+		}
+		ew.headerWritten = true
+	}
+
+	if len(ew.buf) > 0 {
+		if err := ew.flushChunk(); err != nil {
+			return err
+		}
+	}
+
+	sentinel := []byte{0x00, 0x00, 0x00, 0x00}
+	if _, err := ew.w.Write(sentinel); err != nil {
+		return err
+	}
+
+	hmacVal := ew.mac.Sum(nil)
+	if _, err := ew.w.Write(hmacVal); err != nil {
+		return err
+	}
+
+	return nil
+}
+
+type decryptReader struct {
+	r             io.Reader
+	key           []byte
+	gcm           cipher.AEAD
+	mac           hash.Hash
+	headerChecked bool
+	finished      bool
+	outBuf        []byte
+	outPos        int
+}
+
+func DecryptReader(r io.Reader, key []byte) (io.Reader, error) {
+	if len(key) != 32 {
+		return nil, fmt.Errorf("%w: key must be 32 bytes, got %d", ErrInvalidKey, len(key))
+	}
+	k := make([]byte, 32)
+	copy(k, key)
+	return &decryptReader{
+		r:   r,
+		key: k,
+		mac: hmac.New(sha256.New, k),
+	}, nil
+}
+
+func (dr *decryptReader) Read(p []byte) (int, error) {
+	if len(p) == 0 {
+		return 0, nil
+	}
+
+	if dr.outPos < len(dr.outBuf) {
+		n := copy(p, dr.outBuf[dr.outPos:])
+		dr.outPos += n
+		if dr.outPos == len(dr.outBuf) {
+			dr.outBuf = nil
+			dr.outPos = 0
+		}
+		return n, nil
+	}
+
+	if dr.finished {
+		return 0, io.EOF
+	}
+
+	if !dr.headerChecked {
+		header := make([]byte, 3)
+		_, err := io.ReadFull(dr.r, header)
+		if err != nil {
+			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
+				return 0, fmt.Errorf("invalid header: truncated header: %w", err)
+			}
+			return 0, fmt.Errorf("invalid header: %w", err)
+		}
+		if header[0] != 0x4F || header[1] != 0x44 {
+			return 0, errors.New("invalid header: magic mismatch")
+		}
+		if header[2] != 0x01 {
+			return 0, fmt.Errorf("unsupported version: 0x%02x", header[2])
+		}
+		dr.headerChecked = true
+
+		block, err := aes.NewCipher(dr.key)
+		if err != nil {
+			return 0, fmt.Errorf("integrity error: %w", err)
+		}
+		gcm, err := cipher.NewGCM(block)
+		if err != nil {
+			return 0, fmt.Errorf("integrity error: %w", err)
+		}
+		dr.gcm = gcm
+	}
+
+	for {
+		lenBuf := make([]byte, 4)
+		_, err := io.ReadFull(dr.r, lenBuf)
+		if err != nil {
+			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
+				return 0, fmt.Errorf("truncated data: incomplete chunk header: %w", err)
+			}
+			return 0, fmt.Errorf("truncated data: %w", err)
+		}
+
+		chunkLen := binary.BigEndian.Uint32(lenBuf)
+		if chunkLen == 0 {
+			expectedHMAC := make([]byte, 32)
+			_, err := io.ReadFull(dr.r, expectedHMAC)
+			if err != nil {
+				return 0, fmt.Errorf("truncated data: incomplete HMAC: %w", err)
+			}
+			computedHMAC := dr.mac.Sum(nil)
+			if !hmac.Equal(computedHMAC, expectedHMAC) {
+				return 0, errors.New("integrity check failed: HMAC mismatch")
+			}
+			dr.finished = true
+			return 0, io.EOF
+		}
+
+		dr.mac.Write(lenBuf)
+
+		if chunkLen < 28 {
+			return 0, errors.New("integrity error: chunk length too small")
+		}
+
+		chunkData := make([]byte, chunkLen)
+		_, err = io.ReadFull(dr.r, chunkData)
+		if err != nil {
+			return 0, fmt.Errorf("truncated data: incomplete chunk payload: %w", err)
+		}
+
+		dr.mac.Write(chunkData)
+
+		nonce := chunkData[:12]
+		ciphertext := chunkData[12:]
+
+		plaintext, err := dr.gcm.Open(nil, nonce, ciphertext, nil)
+		if err != nil {
+			return 0, fmt.Errorf("integrity error: GCM decryption failed: %w", err)
+		}
+
+		dr.outBuf = plaintext
+		dr.outPos = 0
+
+		n := copy(p, dr.outBuf[dr.outPos:])
+		dr.outPos += n
+		if dr.outPos == len(dr.outBuf) {
+			dr.outBuf = nil
+			dr.outPos = 0
+		}
+		return n, nil
+	}
+}
diff --git a/encryption/encryption_test.go b/encryption/encryption_test.go
