index 0000000..317c65d
--- /dev/null
+++ b/encryption/encryption_test.go
@@ -0,0 +1,249 @@
+package encryption
+
+import (
+	"bytes"
+	"crypto/rand"
+	"encoding/base64"
+	"errors"
+	"io"
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/stretchr/testify/assert"
+	"github.com/stretchr/testify/require"
+)
+
+func TestNewEncryptorKeyLength(t *testing.T) {
+	_, err := NewEncryptor([]byte("shortkey"))
+	require.Error(t, err)
+	assert.True(t, errors.Is(err, ErrInvalidKey))
+
+	validKey := make([]byte, 32)
+	rand.Read(validKey)
+	enc, err := NewEncryptor(validKey)
+	require.NoError(t, err)
+	assert.NotNil(t, enc)
+}
+
+func TestEncryptDecryptRoundTrip(t *testing.T) {
+	key := make([]byte, 32)
+	_, err := rand.Read(key)
+	require.NoError(t, err)
+
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	testCases := [][]byte{
+		{},
+		[]byte("hello world"),
+		make([]byte, 65536),     // 64KB exact
+		make([]byte, 150*1024),  // > 64KB multi-chunk
+	}
+
+	for i, tc := range testCases {
+		if len(tc) > 0 && len(tc) != 11 {
+			rand.Read(tc)
+		}
+
+		var buf bytes.Buffer
+		ew := enc.EncryptWriter(&buf)
+		if len(tc) > 0 {
+			n, err := ew.Write(tc)
+			require.NoError(t, err)
+			assert.Equal(t, len(tc), n)
+		}
+		require.NoError(t, ew.Close())
+
+		// Test idempotent close
+		require.NoError(t, ew.Close())
+
+		dr, err := DecryptReader(&buf, key)
+		require.NoError(t, err)
+
+		decrypted, err := io.ReadAll(dr)
+		require.NoError(t, err, "failed on case %d", i)
+		assert.Equal(t, tc, decrypted)
+	}
+}
+
+func TestTwoEncryptionsDiffer(t *testing.T) {
+	key := make([]byte, 32)
+	rand.Read(key)
+
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	plaintext := []byte("identical plaintext data for testing nonces")
+
+	var buf1, buf2 bytes.Buffer
+	w1 := enc.EncryptWriter(&buf1)
+	w1.Write(plaintext)
+	w1.Close()
+
+	w2 := enc.EncryptWriter(&buf2)
+	w2.Write(plaintext)
+	w2.Close()
+
+	assert.NotEqual(t, buf1.Bytes(), buf2.Bytes())
+}
+
+func TestDecryptHeaderValidation(t *testing.T) {
+	key := make([]byte, 32)
+	rand.Read(key)
+
+	// Invalid magic
+	badMagicData := []byte{0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00}
+	dr, err := DecryptReader(bytes.NewReader(badMagicData), key)
+	require.NoError(t, err)
+	_, err = io.ReadAll(dr)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "invalid header")
+
+	// Unsupported version
+	badVersionData := []byte{0x4F, 0x44, 0x02, 0x00, 0x00, 0x00, 0x00}
+	dr2, err := DecryptReader(bytes.NewReader(badVersionData), key)
+	require.NoError(t, err)
+	_, err = io.ReadAll(dr2)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "unsupported version")
+}
+
+func TestDecryptWrongKeyAndIntegrity(t *testing.T) {
+	key1 := make([]byte, 32)
+	key2 := make([]byte, 32)
+	rand.Read(key1)
+	rand.Read(key2)
+
+	enc, err := NewEncryptor(key1)
+	require.NoError(t, err)
+
+	var buf bytes.Buffer
+	w := enc.EncryptWriter(&buf)
+	w.Write([]byte("secret message"))
+	w.Close()
+
+	data := buf.Bytes()
+
+	// Decrypt with wrong key
+	drWrongKey, err := DecryptReader(bytes.NewReader(data), key2)
+	require.NoError(t, err)
+	_, err = io.ReadAll(drWrongKey)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "integrity")
+
+	// Tamper with HMAC at end
+	tampered := make([]byte, len(data))
+	copy(tampered, data)
+	tampered[len(tampered)-1] ^= 0xFF
+
+	drTampered, err := DecryptReader(bytes.NewReader(tampered), key1)
+	require.NoError(t, err)
+	_, err = io.ReadAll(drTampered)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "integrity")
+}
+
+func TestDecryptTruncatedData(t *testing.T) {
+	key := make([]byte, 32)
+	rand.Read(key)
+
+	enc, err := NewEncryptor(key)
+	require.NoError(t, err)
+
+	var buf bytes.Buffer
+	w := enc.EncryptWriter(&buf)
+	w.Write([]byte("test payload for truncation"))
+	w.Close()
+
+	fullData := buf.Bytes()
+
+	// Cut data in half
+	truncatedData := fullData[:len(fullData)/2]
+	dr, err := DecryptReader(bytes.NewReader(truncatedData), key)
